def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))

    if not alive:
        base = 18.0
        if hp <= 3 or no_water >= 1:
            base = 45.0
        return max(0.0, min(budget, base))

    slots = int(supply // WATER_REQ)
    if slots < 1:
        slots = 1

    prev_bids = []
    danger_scores = []
    max_prev = 0.0
    david_prev = None
    for oid, opp in alive:
        prev = opp.get('previous_trace', {})
        bid = None
        if prev:
            bid = prev.get('bid')
        if bid is not None:
            b = float(bid)
            prev_bids.append(b)
            if b > max_prev:
                max_prev = b
            if oid == 'David':
                david_prev = b
        req = opp.get('water_requirement', WATER_REQ)
        obudget = opp.get('budget', 0.0)
        ohp = opp.get('hp', 10)
        onw = opp.get('no_water_days', 0)
        score = 0.0
        if onw >= 1:
            score += 20.0
        if ohp <= 4:
            score += 18.0
        if obudget > DAILY_SALARY * 4:
            score += 10.0
        if req <= supply:
            score += 5.0
        danger_scores.append(score)

    pressure = max_prev if prev_bids else 40.0
    avg_pressure = sum(prev_bids) / len(prev_bids) if prev_bids else 40.0
    opp_critical = max(danger_scores) if danger_scores else 0.0

    critical_me = hp <= 3 or no_water >= 1
    very_critical_me = hp <= 2 or no_water >= 2

    if slots >= len(alive) + 1:
        bid = 8.0
        if critical_me:
            bid = 22.0
        return max(0.0, min(budget, bid))

    if slots == 1:
        if very_critical_me:
            target = max(72.0, pressure + 2.0)
            if david_prev is not None:
                target = max(target, david_prev + 3.0)
            return max(0.0, min(budget, target))
        if critical_me:
            target = max(54.0, avg_pressure + 1.5)
            if opp_critical >= 20.0:
                target += 4.0
            return max(0.0, min(budget, target))
        return max(0.0, min(budget, 12.0))

    bid = 24.0
    if pressure >= 120.0:
        bid = 26.0
    elif pressure >= 80.0:
        bid = 34.0
    elif pressure >= 55.0:
        bid = pressure + 1.5
    else:
        bid = max(32.0, pressure + 2.0)

    if david_prev is not None and david_prev >= 40.0:
        bid = max(bid, david_prev + 1.5)

    if critical_me:
        bid += 10.0
    if very_critical_me:
        bid += 14.0
    if opp_critical >= 20.0 and not critical_me:
        bid -= 6.0

    if day >= 8 and hp >= 6 and no_water == 0:
        bid -= 4.0

    if budget < 60.0:
        bid = min(bid, budget)
    else:
        bid = min(bid, budget, 88.0)

    if bid < 0.0:
        bid = 0.0
    return bid

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 150
    WATER_REQ = 13
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    prev_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 50

    if my_status['hp'] <= 3:
        return min(my_status['budget'], 120)

    if day_context['supply'] < WATER_REQ + 2:
        return min(my_status['budget'], int(avg_prev * 1.2))

    return min(my_status['budget'], int(avg_prev * 0.95))

