def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    EPISODE_DAYS = 10

    my_hp = my_status['hp']
    my_budget = my_status['budget']
    current_day = day_context['day']
    current_supply = day_context['supply']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    water_slots = int(current_supply / WATER_REQ)

    bid_amount = DAILY_SALARY * 0.45

    if my_hp <= 2:
        bid_amount = DAILY_SALARY * 0.8
    elif my_hp <= 4:
        bid_amount = DAILY_SALARY * 0.65
    elif my_hp <= 6:
        bid_amount = DAILY_SALARY * 0.55

    if num_alive_opponents + 1 > water_slots:
        if water_slots == 1 and num_alive_opponents >= 2:
            bid_amount = max(bid_amount, DAILY_SALARY * 0.75)
        elif water_slots == 2 and num_alive_opponents >= 3:
            bid_amount = max(bid_amount, DAILY_SALARY * 0.6)
        else:
            bid_amount = max(bid_amount, DAILY_SALARY * 0.5)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        if highest_prev_bid >= DAILY_SALARY * 0.8:
            if my_hp > 5 and my_budget > DAILY_SALARY * 3:
                bid_amount = min(bid_amount, highest_prev_bid * 0.8)
            else:
                bid_amount = max(bid_amount, highest_prev_bid + 5)
        elif highest_prev_bid >= DAILY_SALARY * 0.6:
            bid_amount = max(bid_amount, highest_prev_bid + 2.5)

    if current_day >= EPISODE_DAYS - 1 and my_hp <= 3:
        bid_amount = my_budget

    final_bid = min(my_budget, bid_amount)

    return max(1.0, final_bid)
